class Temperature:
    def __init__(self, celsius):
        if not self.is_valid(celsius):
            raise ValueError("temperature below absolute zero")
        self.celsius = celsius

    def fahrenheit(self):
        return self.celsius * 9 / 5 + 32

    @classmethod
    def from_fahrenheit(cls, value):
        return cls((value - 32) * 5 / 9)

    @staticmethod
    def is_valid(value):
        return value >= -273.15

freezing = Temperature.from_fahrenheit(32)
print(freezing.celsius, freezing.fahrenheit())
```

The instance method reads state, the class method constructs the calling class, and the static method checks a stateless rule.
